package domain

import "time"

// Step sources, mirrored from the case_step.source CHECK constraint. Steps may
// only be authored by a human or generated by AI; ai_supplement is reserved for
// node/source content that P7 may add.
const (
	StepSourceUserInput   = NodeSourceUserInput
	StepSourceAIGenerated = NodeSourceAIGenerated
)

// MaxStepsPerCase mirrors the case_step.seq CHECK constraint (1..30).
const MaxStepsPerCase = 30

// CaseStep is one ordered action of a test case. Seq is 1-based and contiguous
// per node (spec §6.1). IDs are application-generated Snowflakes.
type CaseStep struct {
	ID        int64
	NodeID    int64
	Seq       int
	Action    string
	Expected  string
	Data      string
	Source    string
	CreatedAt time.Time
	UpdatedAt time.Time
}
